"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[2840],{6777(e){e.exports=JSON.parse('{"title":"Next.js \uac1c\ubc1c\uc790\ub97c \uc704\ud55c TanStack Start \uba58\ud0c8 \ubaa8\ub378","date":"2026-06-24","coverUrl":"/kudzu-based-bench/assets/notion/8ba1ced75ceec8bd.png","html":"<h1 data-notion-block-id=\\"de25a015-bbcc-4cab-ab7a-1cc3ce02e144\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"a0586df0-1cc7-4d7f-a0aa-4df83b3803a6\\" id=\\"a0586df0-1cc7-4d7f-a0aa-4df83b3803a6\\">Next.js \uac1c\ubc1c\uc790\ub97c \uc704\ud55c TanStack Start \uba58\ud0c8 \ubaa8\ub378</h2><a href=\\"https://www.adarsha.dev/blog/tanstack-mental-model-for-nextjs-developers\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.adarsha.dev/blog/tanstack-mental-model-for-nextjs-developers</a><p data-notion-block-id=\\"2e015434-8cc0-4435-a820-6904f604680b\\">Next.js\uc640 TanStack Start\uc758 \ucc28\uc774\ub97c \uae30\ub2a5 \ube44\uad50\uac00 \uc544\ub2c8\ub77c \'\ubb34\uc5c7\uc744 \uae30\ubcf8\uac12\uc73c\ub85c \ub450\ub294\uac00\'\ub85c \ud480\uc5b4\ub0b8 \uae00\uc785\ub2c8\ub2e4. \uae00\uc774 \uacbd\uace0\ud558\ub294 isomorphic \ub85c\ub354\uc640 \uc11c\ubc84 \ud568\uc218 \uacbd\uacc4 \ubb38\uc81c\uac00 \uc2e4\uc81c\ub85c \ud130\uc9c4 \uc0ac\ub840\uac00 <a href=\\"https://ones-to-watch.ethansup.net/news/post/237e548d-8a8e-80c8-8e59-c60afe0411ca\\">LY corp \ucee8\ud37c\ub7f0\uc2a4\uc758 Version Skew \uc774\uc57c\uae30</a>\uc785\ub2c8\ub2e4. \uacbd\uacc4\ub97c \uba85\uc2dc\ud558\uc9c0 \uc54a\uc73c\uba74 client\uc640 server \ud568\uc218 \uc5f0\uacb0\uc774 \uc5b4\ub5bb\uac8c \uae68\uc9c0\ub294\uc9c0 \uac19\uc774 \ubcf4\uba74 \uc88b\uc2b5\ub2c8\ub2e4. \ucd94\uac00\ub85c TanStack Start\ubcf4\ub2e8 \ub290\ub9ac\uc9c0\ub9cc \uc548\uc815\uc801\uc774\uace0 loader-component-action \ud328\ud134\uc744 \uc9c0\ud5a5\ud558\ub294 React Router\ub3c4 \ud568\uaed8 \uad00\ucc30\ud560 \ub9cc\ud569\ub2c8\ub2e4. \uba38\uc796\uc544, <a href=\\"https://ones-to-watch.ethansup.net/news/post/327e548d-8a8e-807a-94c6-f8ee5a3ccbb6#328e548d-8a8e-8046-9063-efaf7c43e865\\">TanStack Start\uac00 Next.js\uac00 \ub420\uc9c0\ub3c4</a>\uc694.</p><h2 data-notion-block-id=\\"5a69f5eb-9673-4efc-8c72-7f5361524539\\" id=\\"5a69f5eb-9673-4efc-8c72-7f5361524539\\">LLM\uc774 \\"\ud558\uac8c\\" \ub9cc\ub4dc\ub294 \uac83\ubcf4\ub2e4 \\"\ubabb \ud558\uac8c\\" \ub9cc\ub4dc\ub294 \uac8c \ub354 \uc88b\ub2e4</h2><a href=\\"https://polar.sh/blog/orbit-llm-safe-design-system\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://polar.sh/blog/orbit-llm-safe-design-system</a><p data-notion-block-id=\\"7af70ad6-a14c-433d-8716-643a99848065\\">\ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc744 \'\uc9c0\ud0a4\uae38 \ubc14\ub77c\ub294 \uac00\uc774\ub4dc\ub77c\uc778\'\uc5d0\uc11c \'\uc5b4\uae30\ub294 \uac8c \ubd88\uac00\ub2a5\ud55c \uc81c\uc57d\'\uc73c\ub85c \uc62e\uae34 \uc0ac\ub840\uc785\ub2c8\ub2e4. \uc9c0\ub09c \ud638\uc5d0\uc11c \ub2e4\ub8ec <a href=\\"https://ones-to-watch.ethansup.net/news/post/34ae548d-8a8e-8089-b1db-c322e570f0aa#352e548d-8a8e-8068-b3b5-f96d913e7433\\">\\"LLM \uce5c\ud654\\"\ub294 \uc5b4\ub5bb\uac8c \ub2ec\uc131\ub418\uace0 \uc788\ub294\uac00</a>\ub97c \uacb0\uad6d \ubb34\uc5c7\uc73c\ub85c \uc774\ub8e8\ub294\uc9c0, \uadf8 \ud55c \uac00\uc9c0 \uad6c\uccb4\uc801\uc778 \ub2f5\uc774 \uc798\ubabb\ub41c \uac12\uc744 \ud0c0\uc785\uacfc \ud1a0\ud070\uc73c\ub85c \uc544\uc608 \ud45c\ud604 \ubd88\uac00\ub2a5\ud558\uac8c \ub9cc\ub4dc\ub294 \uc774 \ubc29\uc2dd\uc785\ub2c8\ub2e4. tailwind \ub300\uc2e0 \ud1a0\ud070 \uae30\ubc18 CSS-in-JS\ub97c \uc120\ud0dd\ud55c \uc774\uc720\ub3c4 \ub2e4\uc591\ud558\uac8c \ud480\uc5b4\ub0b4\uace0 \uc788\uc73c\ub2c8 \uc2a4\ud0c0\uc77c\ub9c1\uc5d0 \uace0\ubbfc\uc774\uc2e0 \ubd84\ub4e4\uc740 \ud55c \ubc88 \ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"49ffcf57-12cc-447c-8be1-1eda0fa6ca49\\" id=\\"49ffcf57-12cc-447c-8be1-1eda0fa6ca49\\">TanStack Table v9, \ubb34\uc5c7\uc744 \ub2e4\uc2dc \uc9dc\ub098</h2><a href=\\"https://tanstack.com/blog/tanstack-table-v9-typescript-performance\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tanstack.com/blog/tanstack-table-v9-typescript-performance</a><p data-notion-block-id=\\"ad66fe28-acd3-4ab5-8a2f-e6f751ad3c15\\">\ud070 \ud45c\ub97c \ub2e4\ub8e8\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 \uacb0\uad6d \ubd80\ub52a\ud788\ub294 \ubcbd\uc740 \ub300\uc6a9\ub7c9\uc744 \uc5b4\ub5bb\uac8c \ubc84\ud2f0\ub290\ub0d0\uc785\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/304e548d-8a8e-802a-9994-c2dccff3d80a#307e548d-8a8e-80c0-88e6-ebf70ac29af4\\">List Virtualization, \uc2ec\ud654\ubc84\uc804</a>, \uadf8\ub9ac\uace0 <a href=\\"https://ones-to-watch.ethansup.net/news/post/374e548d-8a8e-80ac-9a0c-fa8de4b46b09#378e548d-8a8e-806b-bfd1-ea55f4ce084d\\">Diff \ube60\ub974\uac8c \ubcf4\uc5ec\uc8fc\uae30</a>\ub97c \uac19\uc774 \ubcf4\uba74, \uac00\uc0c1\ud654\ub85c \ubcf4\uc774\ub294 \ud589\uc744 \uc904\uc774\uace0\ub3c4 \ub0a8\ub294 \uba54\ubaa8\ub9ac\uc640 \uc7ac\ub80c\ub354 \ube44\uc6a9\uc744 \ub77c\uc774\ube0c\ub7ec\ub9ac \ucc28\uc6d0\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uae4e\ub294\uc9c0\uac00 \ubcf4\uc785\ub2c8\ub2e4. \ub610\ud55c, DX\ub97c \ucd5c\uc801\ud654\ud558\ub824\ub2e4 \ub9cc\ub09c \ubb38\uc81c\uac00 <a href=\\"https://ones-to-watch.ethansup.net/news/post/109e548d-8a8e-8006-bd2d-e5cd889b8dc5#109e548d-8a8e-8079-8c80-edd09db9fe25\\">Tanstack Router\uc758 TypeScript \uc131\ub2a5 \ucd5c\uc801\ud654\ud558\uae30</a>\uc640 \uac19\uc740 \ubb38\uc81c\ub97c \uac16\uace0 \uc788\uc73c\ubbc0\ub85c, \ub77c\uc774\ube0c\ub7ec\ub9ac \uac1c\ubc1c\uc790\uc5d0\uac8c \ubb34\uc5c7\ubcf4\ub2e4\ub3c4 \uc911\uc694\ud55c \ubd80\ubd84\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"28d2f17f-49a7-42c1-a235-9d7f9d1ec026\\" id=\\"28d2f17f-49a7-42c1-a235-9d7f9d1ec026\\">App Router\ub85c \ub290\ub9b0 \uc751\ub2f5\uc744 80% \uc904\uc774\uae30\uae4c\uc9c0</h2><a href=\\"https://dev.to/subito/how-we-cut-slow-responses-by-80-migrating-to-nextjs-app-router-37da\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://dev.to/subito/how-we-cut-slow-responses-by-80-migrating-to-nextjs-app-router-37da</a><p data-notion-block-id=\\"995b5774-4ef7-4803-a404-9bc42081c494\\">RSC\uc640 \uc2a4\ud2b8\ub9ac\ubc0d\uc774 \uc751\ub2f5\uc744 \ube60\ub974\uac8c \ud55c\ub2e4\ub294 \uc598\uae30\ub294 \ub9ce\uc9c0\ub9cc, \uc2e4\uc81c\ub85c \ubb34\uc5c7\uc774 \ube68\ub77c\uc9c0\uace0 \uc5b4\ub514\uc11c \ub9c9\ud788\ub294\uc9c0\ub294 \ub530\ub85c \ubd10\uc57c \ud569\ub2c8\ub2e4. \uc5ec\ub7ec \uae00\uc5d0\uc11c RSC\ub97c <a href=\\"https://ones-to-watch.ethansup.net/news/post/d4f23197-313d-4572-8daa-b392343947bb#d29ccd0e-2c07-46d1-aae1-7e9f69a5fe36\\">RSC \ub610\ud55c \ud3ed\ud3ec \uc694\uccad \ubb38\uc81c\uac00 \uc788\ub2e4</a>, <a href=\\"https://ones-to-watch.ethansup.net/news/post/374e548d-8a8e-80ac-9a0c-fa8de4b46b09#378e548d-8a8e-8035-8368-c02daf73ca43\\">Conductor\uc758 Rewrite \uc911 \ubb34\uc5c7\uc774 \uc131\ub2a5\uc744 \ub192\uc600\ub098</a>\ub85c \ub2e4\ub918\ub294\ub370, \uc774 \uae00\uc740 \uadf8 \uc774\ub860\uc774 \ud55c \uc11c\ube44\uc2a4\uc758 \ud504\ub85c\ub355\uc158\uc5d0\uc11c \uc5b4\ub5a4 \uc778\ud504\ub77c \ubcbd\uc5d0 \ubd80\ub52a\ud788\ub294\uc9c0, \uadf8\ub9ac\uace0 \ud504\ub808\uc784\uc6cc\ud06c, \ub7f0\ud0c0\uc784, CDN, \ubaa8\ub2c8\ud130\ub9c1\uc774 \ud55c \ubab8\uc774 \ub418\uc5b4 \uad6c\ub3d9 \ubc29\uc2dd\uc744 \uc77c\uce58\ud574\uc57c \uc131\ub2a5 \uc774\ub4dd\uc774 \uc2e4\ud604\ub41c\ub2e4\ub294 \uc0ac\uc2e4\ub3c4 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"5608053b-97b1-4701-bd33-8c73ba339446\\" id=\\"5608053b-97b1-4701-bd33-8c73ba339446\\">psql \ub2e4\uc2dc \ub9cc\ub4e4\uae30</h2><a href=\\"https://neon.com/blog/shipping-psql-without-psql\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://neon.com/blog/shipping-psql-without-psql</a><p data-notion-block-id=\\"6b49d613-cfea-43f5-85f1-6000bd07cc1e\\">\'AI\uac00 \uac70\uc758 \ub2e4 \uc9f0\ub2e4\'\uace0 \uba3c\uc800 \ubc1d\ud788\uace0, \uadf8\ub7fc\uc5d0\ub3c4 \ubbff\uc744 \uc218 \uc788\ub294 \uc774\uc720\ub97c \ucf54\ub4dc\uac00 \uc544\ub2c8\ub77c \uac80\uc99d \uc7a5\uce58\uc5d0\uc11c \ucc3e\ub294 \uae00\uc785\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/35de548d-8a8e-8011-af21-fb98c8fd2944\\">React \ud574\uccb4\ubd84\uc11d\uae30</a>\uc640 \uc774\uc5b4\uc9d1\ub2c8\ub2e4. AI\ub85c \uae30\uc874 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ub2e4\uc2dc \uc9dc \uc0b0\ucd9c\ubb3c\uc744 \uc5b4\ub5bb\uac8c \ubd10\uc57c \ud558\ub098\ub77c\ub294 \ubb3c\uc74c\uc5d0, \uc774 \uae00\uc740 \uc2e0\ub8b0\uac00 conformance \ud558\ub124\uc2a4\uc640 \uc801\ub300\uc801 \ub9ac\ubdf0, CI\uc5d0\uc11c \ub098\uc628\ub2e4\ub294 \uad6c\uccb4\uc801\uc778 \ub2f5\uc744 \uc90d\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"fab1effb-1161-4f33-867a-b9cb3e812243\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"e2f82e35-d2e9-4504-8bbf-d2efb92a3dc4\\" id=\\"e2f82e35-d2e9-4504-8bbf-d2efb92a3dc4\\">\ubaa8\ub4c8 \uc2dc\uc2a4\ud15c \uc758\uc874\uc131 \uc8fc\uc785, \uadf8 \ud55c\uacc4</h2><a href=\\"https://www.jayfreestone.com/writing/module-level-dependency-injection-react/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.jayfreestone.com/writing/module-level-dependency-injection-react/</a><p data-notion-block-id=\\"51866967-3b31-4ded-a424-216df78b9bd6\\">Next.js \uc9c4\uc601\uc5d0\uc11c \uad8c\ud558\ub294 \'\ubaa8\ub4c8 \uc2dc\uc2a4\ud15c\uc744 DI\ub85c \uc4f0\ub77c\'\ub294 \uc870\uc5b8\uc758 \ud2b8\ub808\uc774\ub4dc\uc624\ud504\ub97c \uc9da\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"5b99c99e-2f61-4175-8df3-6885eba818bc\\" id=\\"5b99c99e-2f61-4175-8df3-6885eba818bc\\">\uc624\ud508\uc18c\uc2a4\uc758 alpha, beta, canary\ub97c \uc120\ud0dd\ud574\uc57c \ud560 \ub54c\ub294 \uc5b8\uc81c\uc77c\uae4c</h2><a href=\\"https://www.prisma.io/blog/bun-rust-rewrite-prisma-compute\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.prisma.io/blog/bun-rust-rewrite-prisma-compute</a><h2 data-notion-block-id=\\"b2ad4a37-e72d-4992-9a45-8372eac9df22\\" id=\\"b2ad4a37-e72d-4992-9a45-8372eac9df22\\">View Transition pseudo tree \ud574\ubd80</h2><a href=\\"https://master.dev/blog/demystifying-the-view-transition-pseudo-tree/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://master.dev/blog/demystifying-the-view-transition-pseudo-tree/</a><h2 data-notion-block-id=\\"369c0be3-4c6f-4a92-af55-739bf6b76e3b\\" id=\\"369c0be3-4c6f-4a92-af55-739bf6b76e3b\\">\uc6f9 \ud45c\uc900\uc73c\ub85c \ub2e4\ud06c \ubaa8\ub4dc \uad6c\ud604\ud558\uae30</h2><a href=\\"https://olliewilliams.xyz/blog/dark-mode/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://olliewilliams.xyz/blog/dark-mode/</a><h2 data-notion-block-id=\\"4000b3b2-800c-4577-a9e9-8ce8ff4087a1\\" id=\\"4000b3b2-800c-4577-a9e9-8ce8ff4087a1\\">\ucee4\uc2a4\ud130\ub9c8\uc774\uc988 \uac00\ub2a5\ud55c select \uc0ac\uc6a9\ubc95</h2><a href=\\"https://webkit.org/blog/18117/the-golden-rule-of-customizable-select/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://webkit.org/blog/18117/the-golden-rule-of-customizable-select/</a><h2 data-notion-block-id=\\"12e40b11-9aae-48a9-b671-afbb2adbf82a\\" id=\\"12e40b11-9aae-48a9-b671-afbb2adbf82a\\">React Native \uc2dc\uc791 \uc2dc\uac04\uc744 50% \uc904\uc778 \ud6c4\uae30</h2><a href=\\"https://medium.com/@pumpdotfun_/how-we-improved-the-startup-time-of-our-app-by-50-b3107bed1bf9\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://medium.com/@pumpdotfun_/how-we-improved-the-startup-time-of-our-app-by-50-b3107bed1bf9</a><h2 data-notion-block-id=\\"7f22dcbf-1184-4eee-9783-223aaa1f2027\\" id=\\"7f22dcbf-1184-4eee-9783-223aaa1f2027\\">git worktree\uac00 \ubb50\uace0 \uc65c \uc368\uc57c \ud558\ub098</h2><a href=\\"https://github.blog/ai-and-ml/github-copilot/what-are-git-worktrees-and-why-should-i-use-them/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.blog/ai-and-ml/github-copilot/what-are-git-worktrees-and-why-should-i-use-them/</a><h1 data-notion-block-id=\\"d29c4238-d23b-41a9-a5f1-ec878f498dda\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://reactnative.dev/blog/2026/06/11/react-native-0.86\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://reactnative.dev/blog/2026/06/11/react-native-0.86</a><p data-notion-block-id=\\"5f033e12-3389-46f1-a3b5-9e640628b2ee\\">React Native 0.86\uc774 \ub098\uc654\uc2b5\ub2c8\ub2e4. Android 15+ Edge-to-Edge\ub97c measureInWindow, KeyboardAvoidingView, Dimensions \ub4f1 596\uac1c \ucee4\ubc0b\uc73c\ub85c \uc804\uba74 \uc190\ubd24\uace0, DevTools\uc5d0 \ub77c\uc774\ud2b8\uc640 \ub2e4\ud06c \ubaa8\ub4dc \uc5d0\ubbac\ub808\uc774\uc158\uc774 \ub4e4\uc5b4\uc654\uc2b5\ub2c8\ub2e4. 0.83 \uc774\ud6c4 \ub450 \ubc88\uc9f8\ub85c \uc0ac\uc6a9\uc790 \ub300\uba74 breaking change\uac00 \uc5c6\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://oxc.rs/docs/guide/usage/linter/rules/react/react-compiler.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://oxc.rs/docs/guide/usage/linter/rules/react/react-compiler.html</a><p data-notion-block-id=\\"c4e12ea3-4f5d-41d9-aab7-31b37ddb5c40\\">oxc\uac00 react-compiler \ub9b0\ud2b8 \uaddc\uce59\uc744 \ucd94\uac00\ud588\uc2b5\ub2c8\ub2e4. React Compiler \ubd84\uc11d\uc744 \uc9c1\uc811 \ub3cc\ub824 \uc870\uac74\ubd80 \ud6c5 \ud638\ucd9c, \ub80c\ub354 \uc911 setState, ref \uc811\uadfc, props\ub098 state \ubcc0\uacbd \uac19\uc740 Rules of React \uc704\ubc18\uc744 \uc7a1\uc544\ub0c5\ub2c8\ub2e4.</p><a href=\\"https://nerdy.dev/prop-for-that\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nerdy.dev/prop-for-that</a><p data-notion-block-id=\\"661f17c8-0c06-4ecc-9990-42bb9d01f36e\\">\ud3ec\uc778\ud130 \uc704\uce58, \uc785\ub825\uac12, \uc2a4\ud06c\ub864\ubc14 \ud06c\uae30, \uc774\ubbf8\uc9c0 \uc0c9\uc0c1\ucc98\ub7fc CSS\uac00 \uc544\uc9c1 \ubaa8\ub974\ub294 \ub3d9\uc801 \uc815\ubcf4\ub97c JS\ub85c CSS \ucee4\uc2a4\ud140 \ud504\ub85c\ud37c\ud2f0\uc5d0 \ud758\ub824\ub123\uc5b4, \uc21c\uc218 CSS\ub9cc\uc73c\ub85c \ubcf5\uc7a1\ud55c \ud6a8\uacfc\ub97c \ub9cc\ub4e4\uac8c \ub3d5\ub294 \ud328\ud134\uacfc \ub77c\uc774\ube0c\ub7ec\ub9ac \ubaa8\uc74c\uc785\ub2c8\ub2e4.</p><a href=\\"https://nubjs.com/blog/introducing-nub\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nubjs.com/blog/introducing-nub</a><p data-notion-block-id=\\"b2881e1f-b26e-4e9b-98cd-061e50ce6401\\">Nub\uc740 Node\ub97c \ub300\uccb4\ud558\uc9c0 \uc54a\uace0 \uae30\uc874 Node \uc704\uc5d0 \uc5b9\ub294 Rust CLI\uc785\ub2c8\ub2e4. TypeScript \uc2e4\ud589\uacfc \uc2a4\ud06c\ub9bd\ud2b8 \ub7ec\ub108, CLI \uc2e4\ud589\uc744 \ub354 \ube60\ub974\uac8c \ubb36\uc740 \ud234\ud0b7\uc73c\ub85c, Bun\uc774\ub098 Deno\ucc98\ub7fc \ub7f0\ud0c0\uc784\uc744 \uac08\uc544\uce58\uc6b0\uc9c0 \uc54a\uc73c\uba74\uc11c \uac1c\ubc1c \uacbd\ud5d8\ub9cc \ud604\ub300\ud654\ud558\ub824\ub294 \uc811\uadfc\uc785\ub2c8\ub2e4.</p><a href=\\"https://github.com/mui/base-ui/releases/tag/v1.6.0\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/mui/base-ui/releases/tag/v1.6.0</a><p data-notion-block-id=\\"546b4ddf-090e-49c5-bc34-fd20bf186e02\\">Base UI v1.6.0\uc740 \ud3fc \uac80\uc99d, \ud3ec\ucee4\uc2a4 \uad00\ub9ac, \ud3ec\uc9c0\uc154\ub2dd \ub4f1 \uc5ec\ub7ec \ucef4\ud3ec\ub10c\ud2b8\uc758 \uc5e3\uc9c0 \ucf00\uc774\uc2a4\ub97c \uc815\ub9ac\ud55c \uc548\uc815\ud654 \ub9b4\ub9ac\uc2a4\uc785\ub2c8\ub2e4. OTP Field \ub124\uc784\uc2a4\ud398\uc774\uc2a4 \ubcc0\uacbd\uc774 \uc8fc\uc694 \ubcc0\ub3d9\uc774\ub77c \uc5c5\uadf8\ub808\uc774\ub4dc \uc2dc \ud655\uc778\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.</p><a href=\\"https://github.com/react/react/pull/36173\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/react/react/pull/36173</a><p data-notion-block-id=\\"eee6de43-69a3-4acf-aeac-ae55e240ea60\\">React Compiler\ub97c TypeScript\uc5d0\uc11c \uac19\uc740 \uc544\ud0a4\ud14d\ucc98\ub85c Rust\uc5d0 \uc62e\uae34 PR\uc785\ub2c8\ub2e4. Babel \ud50c\ub7ec\uadf8\uc778 \uae30\uc900 \uc57d \uc138 \ubc30, \ubcc0\ud658 \ub85c\uc9c1\ub9cc \ubcf4\uba74 \uc57d \uc5f4 \ubc30 \ube68\ub77c\uc84c\uace0 OXC\uc640 SWC \ud1b5\ud569 \uc608\uc81c\ub3c4 \ud568\uaed8 \ub4e4\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://remix.run/blog/react-router-v8\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://remix.run/blog/react-router-v8</a><p data-notion-block-id=\\"15c0ef40-3174-4f44-b846-d573e3beb86d\\">React Router v8\uc740 \'\uc9c0\ub8e8\ud55c \uba54\uc774\uc800\'\ub97c \ud45c\ubc29\ud558\uba70 \uc5f0 1\ud68c \uba54\uc774\uc800 \uc77c\uc815\uc744 \ucc44\ud0dd\ud588\uc2b5\ub2c8\ub2e4. Node 22+, React 19.2.7+, Vite 7+\ub97c \ucd5c\uc18c \uc694\uac74\uc73c\ub85c \uc7a1\uace0 ESM \uc804\uc6a9\uc73c\ub85c \uc815\ub9ac\ub410\uc2b5\ub2c8\ub2e4.</p>"}')}}]);